"use client";

import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import DashboardClient from "@/components/dashboard/DashboardClient";
import { Loader2 } from "lucide-react";
import { orderCountsTowardSellerRevenue } from "@/lib/sellerOrderPayoutFlow";

export default function DashboardPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  
  const [store, setStore] = useState<any>(null);
  const [products, setProducts] = useState<any[]>([]);
  const [orders, setOrders] = useState<any[]>([]);
  const [stats, setStats] = useState({ revenue: 0, productCount: 0, views: 0 });
  const loadDashboardData = useCallback(async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      
      if (!user) {
        router.push("/login");
        return;
      }

      const { data: storeData } = await supabase
        .from("stores")
        .select("*")
        .eq("owner_id", user.id) 
        .maybeSingle();

      if (!storeData) {
        const { data: prof } = await supabase
          .from("profiles")
          .select("is_seller, onboarding_completed, onboarding_step")
          .eq("id", user.id)
          .maybeSingle();
        if (!prof?.is_seller) {
          router.replace("/account");
          return;
        }
        const completedSeller =
          prof?.onboarding_completed === true || String(prof?.onboarding_step || "").toLowerCase() === "done";
        if (completedSeller) {
          router.replace("/account");
          return;
        }
        router.replace("/onboarding/seller/identity");
        return;
      }

      setStore(storeData);

      const { data: productsData } = await supabase
        .from("products")
        .select("*, categories(name)")
        .eq("seller_id", storeData.owner_id)
        .order("created_at", { ascending: false });
      
      setProducts(productsData || []);

      const { data: ordersData } = await supabase
        .from("orders")
        .select("*")
        .eq("store_id", storeData.id)
        .order("created_at", { ascending: false });

      setOrders(ordersData || []);

      const revenue = ordersData?.reduce((acc, order) => {
        return acc + (orderCountsTowardSellerRevenue(order.status) ? Number(order.total_amount) || 0 : 0);
      }, 0) || 0;

      const count = productsData?.length || 0;
      
      setStats({ 
        revenue, 
        productCount: count, 
        views: storeData.view_count || 0 
      });

    } catch (error) {
      console.error("Dashboard Load Error:", error);
    } finally {
      setLoading(false);
    }
  }, [router]);

  useEffect(() => {
    loadDashboardData();

    const channel = supabase
      .channel('dashboard-updates')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, () => loadDashboardData())
      .on('postgres_changes', { event: '*', schema: 'public', table: 'stores' }, () => loadDashboardData())
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [loadDashboardData]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-8 h-8 animate-spin text-gray-400" />
      </div>
    );
  }

  if (!store) return null;

  return (
    <div className="min-h-screen bg-gray-50 p-4 md:p-8 space-y-6">
      

      <DashboardClient 
        store={store} 
        initialProducts={products} 
        initialOrders={orders}
        stats={stats}
      />
    </div>
  );
}